import React, { useEffect, useState } from "react";
import { Pie } from "react-chartjs-2";
import "./App.css";
import {
  Chart as ChartJS,
  ArcElement,
  Tooltip,
  Legend
} from "chart.js";

ChartJS.register(ArcElement, Tooltip, Legend);

const PortfolioSummary = ({ assets, tableData }) => {
  const [summary, setSummary] = useState(null);

  // Fetch IRR + MOIC + WAL backend summary
  useEffect(() => {
    fetch("/api/portfolio_summary")
      .then(res => res.json())
      .then(data => setSummary(data));
  }, []);

  if (!assets || assets.length === 0 || !tableData || !summary) {
    return <div>Loading portfolio summary…</div>;
  }

  /* ============================
      CLIENT-SIDE CALCULATIONS
     ============================ */

  // Distinct companies
  const distinctCompanies = new Set(
    assets.map(a => a.Company__Issuer_Name)
  ).size;

  // Totals
  const totalCommitted = assets.reduce(
    (sum, a) => sum + Number(a.Committed_EUR || 0), 0
  );

  const totalFunded = assets.reduce(
    (sum, a) => sum + Number(a.Funded_EUR || 0), 0
  );

  // Weighted Average Coupon (WAC)
  const WAC =
    assets.reduce(
      (sum, a) =>
        sum +
        Number(a.Total_Cash_Margin || 0) * Number(a.Funded_EUR || 0),
      0
    ) / (totalFunded || 1);

  /* ============================
     PIE CHART DATA
     ============================ */

  // Instrument type breakdown
  const instrumentCounts = assets.reduce((acc, a) => {
    acc[a.Instrument_Type] = (acc[a.Instrument_Type] || 0) + 1;
    return acc;
  }, {});

  const instrumentChart = {
    labels: Object.keys(instrumentCounts),
    datasets: [
      {
        data: Object.values(instrumentCounts),
        backgroundColor: ["#2563eb", "#10b981", "#f59e0b", "#ef4444"]
      }
    ]
  };

  // Currency breakdown
    // Count CCY frequency
    const ccyCounts = assets.reduce((acc, a) => {
    acc[a.Ccy] = (acc[a.Ccy] || 0) + 1;
    return acc;
    }, {});

    // Convert to percentages
    const totalCcy = Object.values(ccyCounts).reduce((a, b) => a + b, 0);

    const ccyPercentages = Object.fromEntries(
    Object.entries(ccyCounts).map(([ccy, count]) => [
    ccy,
    (count / totalCcy) * 100
    ])
    );

    // Chart.js dataset
    const ccyChart = {
    labels: Object.keys(ccyPercentages),
    datasets: [
    {
    data: Object.values(ccyPercentages),
    backgroundColor: ["#6366f1", "#14b8a6", "#f43f5e", "#a78bfa"],
    hoverOffset: 4
    }
    ]
    };

  return (
    <div style={{ marginTop: "0.5rem" }}>
      <h2 style={titleStyle}>Portfolio Summary</h2>

      {/* Summary Table */}
      <table style={summaryTableStyle}>
            <tbody>
                <tr style={summaryRowStyle}>
                <td style={summaryCellLabel}>Distinct Companies</td>
                <td style={summaryCellValue}>{distinctCompanies}</td>
                </tr>

                <tr style={summaryRowStyle}>
                <td style={summaryCellLabel}>Total Committed</td>
                <td style={summaryCellValue}>{parseFloat(totalCommitted).toLocaleString("en-GB", { maximumFractionDigits: 0 })}</td>
                </tr>

                <tr style={summaryRowStyle}>
                <td style={summaryCellLabel}>Total Funded</td>
                <td style={summaryCellValue}>{parseFloat(totalFunded).toLocaleString("en-GB", { maximumFractionDigits: 0 })}</td>
                </tr>

                <tr style={summaryRowStyle}>
                <td style={summaryCellLabel}>Weighted Avg Life (WAL)</td>
                <td style={summaryCellValue}>
                    {summary.WAL_Years ? summary.WAL_Years.toFixed(2) + " yrs" : "N/A"}
                </td>
                </tr>

                <tr style={summaryRowStyle}>
                <td style={summaryCellLabel}>Weighted Avg Coupon (WAC)</td>
                <td style={summaryCellValue}>{(WAC * 100).toFixed(2)}%</td>
                </tr>

                <tr style={summaryRowStyle}>
                <td style={summaryCellLabel}>IRR (Annualised)</td>
                <td style={summaryCellValue}>
                    {summary.IRR_Annualised
                    ? (summary.IRR_Annualised * 100).toFixed(2) + "%"
                    : "N/A"}
                </td>
                </tr>

                <tr style={summaryRowStyle}>
                <td style={summaryCellLabel}>MOIC</td>
                <td style={summaryCellValue}>
                    {summary.MOIC ? summary.MOIC.toFixed(2) + "x" : "N/A"}
                </td>
                </tr>
                </tbody>
            </table>

      {/* PIE CHARTS */}
      <div style={chartsContainer}>
        <div style={pieBox}>
          <h3 style={chartTitle}>Instrument Type</h3>
          <Pie 
            data={instrumentChart}
            options={{
                plugins: {
                tooltip: {
                    callbacks: {
                    label: function (context) {
                        return `${context.label}: ${context.raw.toFixed(0)}%`;
                    }
                    }
                }
                }
            }}
            />
        </div>

        <div style={pieBox}>
          <h3 style={chartTitle}>Currency (CCY)</h3>
          <Pie 
            data={ccyChart}
            options={{
                plugins: {
                tooltip: {
                    callbacks: {
                    label: function (context) {
                        return `${context.label}: ${context.raw.toFixed(0)}%`;
                    }
                    }
                }
                }
            }}
            />
        </div>
      </div>
    </div>
  );
};

export default PortfolioSummary;

/* ============================
   SOPHISTICATED SUMMARY TABLE
   ============================ */

const summaryTableStyle = {
  width: "80%",
  maxWidth: "600px",
  borderCollapse: "separate",
  borderSpacing: 0,
  fontFamily: "Inter, sans-serif",
  fontSize: "13px",
  borderRadius: "10px",
  overflow: "hidden",
  boxShadow: "0 2px 8px rgba(0,0,0,0.08)",
  marginBottom: "0rem",
  height: "10px"
};

const summaryRowStyle = {
  background: "#ffffff",
  borderBottom: "1px solid #e5e7eb"
};

const summaryCellLabel = {
  padding: "8px 12px",
  fontWeight: 600,
  background: "#f8fafc",
  borderRight: "1px solid #e5e7eb",
  whiteSpace: "nowrap"
};

const summaryCellValue = {
  padding: "8px 12px",
  textAlign: "right",
  background: "#ffffff",
  whiteSpace: "nowrap",
  height: "18px"
};

const titleStyle = {
  fontFamily: "Inter, sans-serif",
  fontSize: "18px",
  fontWeight: 600,
  color: "#2563eb",
  marginBottom: "1rem"
};

/* ============================
   PIE CHART CONTAINERS
   ============================ */

const chartsContainer = {
  display: "flex",
  gap: "2rem",
  marginTop: "2rem",
  flexWrap: "wrap",
  height:"300px"
};

const pieBox = {
  width: "270px",
  height: "300px",
  background: "white",
  padding: "2rem",
  borderRadius: "10px",
  border: "1px solid #e5e7eb",
  boxShadow: "0 2px 8px rgba(0,0,0,0.05)"
};

const chartTitle = {
  textAlign: "center",
  marginBottom: "1rem",
  fontSize: "15px",
  fontWeight: 600,
  fontFamily: "Inter, sans-serif",
  color: "#374151"
};
