import React from "react";

const AssetsTable = ({ assets, assetsError }) => {
  // Error handling
  if (assetsError) {
    return <div style={{ color: "red" }}>{assetsError}</div>;
  }

  // Safe loading check
  if (!assets || !Array.isArray(assets) || assets.length === 0) {
    return <div>Loading assets...</div>;
  }

  // Safely extract columns
  const columns = Object.keys(assets[0] || {});

  const columnsToShow = [
    "Model_Ref",
    "Company__Issuer_Name",
    "Instrument_Name",
    "Instrument_Type",
    "Signing_Date",
    "Initial_Funding_Date",
    "Exit_Date",
    "Maturity_Date",
    "Term",
    "Ccy",
    "Committed_EUR",
    "Funded_EUR",
    "Margin",
    "Total_Cash_Margin",
    "Upfront_Fees__OID",
    "PIK"
  ];

  const percentageColumns = [
    "Upfront_Fees__OID",
    "Margin",
    "Total_Cash_Margin",
    "PIK"
  ];

  const dateColumns = [
    "Signing_Date",
    "Initial_Funding_Date",
    "Exit_Date",
    "Maturity_Date"
  ];

  const numberColumns = [
    "Committed_EUR",
    "Funded_EUR"
  ];

  return (
    <div className="table-wrap">

      <h4 className="table-title">Assets</h4>

      <div className="table-scroll">
        <table className="asset-table">

          {/* HEADER */}
          <thead>
            <tr>
                {columnsToShow
                .filter(col => columns.includes(col))
                .map(col => (
                    <th key={col}>{col}</th>
                ))}
            </tr>
            </thead>

          {/* BODY */}
          <tbody>
            {assets.map((row, idx) => (
                <tr key={idx}>
                {columnsToShow
                    .filter(col => columns.includes(col))
                    .map(col => {
                    let value = row[col];
                    // Percentage formatting
                    if (percentageColumns.includes(col) && value != null && value !== "") {
                        value = `${(parseFloat(value) * 100).toFixed(2)}%`;
                    }
                    // Date formatting
                    if (dateColumns.includes(col) && value) {
                        const dateObj = new Date(value);
                        if (!isNaN(dateObj)) {
                        value = dateObj.toISOString().slice(0, 10);
                        }
                    }
                    // Number formatting
                    if (numberColumns.includes(col)) {
                        value = parseFloat(value).toLocaleString("en-US", {
                        minimumFractionDigits: 0,
                        maximumFractionDigits: 0
                        });
                    }
                    return (
                        <td key={col} style={{ whiteSpace: "nowrap" }}>
                        {value}
                        </td>
                    );
                    })}
                </tr>
            ))}
            </tbody>

        </table>
      </div>

    </div>
  );
};

export default AssetsTable;
