import React, { useState, useEffect } from "react";
import "./App.css";

import AssetsTable from "./Assets";
import PortfolioCashflowView from "./Cashflow";
import PortfolioWithAssumptions from "./Assumptions";
import PortfolioSummary from "./PortfolioSummary";

function App() {
  // Summary widget states (from your earlier code)
  const [a, setA] = useState("");
  const [b, setB] = useState("");
  const [result, setResult] = useState(null);
  const [error, setError] = useState("");

  // ASSETS STATE
  const [assets, setAssets] = useState([]);
  const [assetsError, setAssetsError] = useState("");

  // CASHFLOW STATE
  const [tableData, setTableData] = useState(null);

  // Load assets ONCE
  useEffect(() => {
    fetch("/api/read_assets")
      .then((res) => res.json())
      .then((data) => {
        if (data.data) {
          setAssets(data.data);
        } else {
          setAssetsError(data.error || "Error loading assets");
        }
      })
      .catch(() => setAssetsError("Network error loading assets"));
  }, []);

  // Load initial cashflows ONCE
  useEffect(() => {
    fetch("/api/cfs")
      .then((res) => res.json())
      .then((data) => setTableData(data))
      .catch(() => console.log("Error loading baseline cashflows"));
  }, []);

  // Your small "Add Two Numbers" function
  const handleAdd = async (e) => {
    e.preventDefault();
    setError("");
    setResult(null);
 

    try {
      const response = await fetch("/api/add", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ a, b }),
      });

      const data = await response.json();

      if (response.ok) {
        setResult(data.result);
      } else {
        setError(data.error || "Error occurred");
      }
    } catch (err) {
      setError("Network error");
    }
  };

  return (
    <div style={{ display: "flex", gap: "2rem", alignItems: "flex-start" }}>

      {/* LEFT COLUMN --------------------------------------------------------- */}
      <div style={{ flex: 1 }}>


       <PortfolioWithAssumptions
          assets={assets}
          assetsError={assetsError}
          tableData={tableData}
          setTableData={setTableData}
          setAssets={setAssets}
        />

      </div>

      {/* RIGHT COLUMN -------------------------------------------------------- */}
      <div style={{ width: "500px" }}>
        <div style={{ maxWidth: 400, margin: "0.5rem auto", textAlign: "left" }}>
          <PortfolioSummary assets={assets} tableData={tableData} />
        </div>
      </div>
    </div>
  );
}

export default App;
