import React, { useState } from "react";
import AssetsTable from "./Assets";
import PortfolioCashflowView from "./Cashflow";

const PortfolioWithAssumptions = ({ 
  assets, 
  assetsError, 
  tableData, 
  setTableData, 
  setAssets 
}) => {

  const [marginShock, setMarginShock] = useState(0);
  const [exitShockMonths, setExitShockMonths] = useState(0);
  const [loading, setLoading] = useState(false);

  const applyAssumptions = async () => {
    setLoading(true);

    const payload = {
      margin_shock_bps: Number(marginShock),
      exit_shock_months: Number(exitShockMonths)
    };

    const res = await fetch("/api/recompute-cashflows", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });

    const updated = await res.json();

    // update the parent (App.jsx) state
    setAssets(updated.assets);
    setTableData(updated.cashflows);

    setLoading(false);
  };

  if (!tableData || !assets) return <div>Loading…</div>;

  return (
    <div style={{ marginTop: "0rem" }}>

      {/* TWO TABLES ----------------------------------------------------- */}
      <div style={{ marginBottom: "2rem" }}>

        <AssetsTable assets={assets} assetsError={assetsError} />

        <PortfolioCashflowView tableData={tableData} />
      </div>

      {/* ASSUMPTIONS PANEL ---------------------------------------------- */}
      <div style={panelStyle}>
        <h3 style={{ marginTop: 0, fontFamily: "Arial, sans-serif", fontSize: "15px" }}>Adjust Assumptions</h3>

        <div style={inputRow}>
          <label>Margin Shock (bps):</label>
          <input 
            type="number"
            value={marginShock}
            onChange={e => setMarginShock(e.target.value)}
            style={inputStyle}
          />
        </div>

        <div style={inputRow}>
          <label>Exit Shift (months):</label>
          <input 
            type="number"
            value={exitShockMonths}
            onChange={e => setExitShockMonths(e.target.value)}
            style={inputStyle}
          />
        </div>

        <button 
          onClick={applyAssumptions}
          style={buttonStyle}
          disabled={loading}
        >
          {loading ? "Recalculating…" : "Apply Changes"}
        </button>
      </div>
    </div>
  );
};

export default PortfolioWithAssumptions;

const panelStyle = {
  width: "100%",
  maxWidth: "450px",
  maxHeight: "200px",
  padding: "1rem",
  border: "1px solid #ddd",
  borderRadius: "8px",
  background: "#f8fafc"
};

const inputRow = {
  display: "flex",
  justifyContent: "space-between",
  alignItems: "center",
  marginBottom: "1rem",
  fontFamily: "Arial, sans-serif",
  fontSize: "12px"
};

const inputStyle = {
  width: "120px",
  padding: "4px",
  fontSize: "12px"
};

const buttonStyle = {
  width: "100%",
  padding: "8px",
  background: "#2563eb",
  color: "white",
  border: "none",
  borderRadius: "6px",
  fontSize: "15px",
  cursor: "pointer"
};
