import React from "react";

/* ============================================
   INTERNAL TABLE COMPONENT WITH MODERN STYLING
   ============================================ */

const CashflowTable = ({ hcData }) => {
  if (!hcData) return <div>Loading cashflows...</div>;

  const { categories = [], series = [] } = hcData;

  return (
    <div style={tableWrapperStyle}>
      <table style={tableStyle}>

        {/* HEADER */}
        <thead>
          <tr>
            {/* Sticky left metric header */}
            <th style={{ ...thStyle, ...stickyLeft }}>Metric</th>

            {categories.map(date => (
              <th key={date} style={thStyle}>{date}</th>
            ))}
          </tr>
        </thead>

        {/* BODY */}
        <tbody>
          {series.map((metric, idx) => (
            <tr key={idx} style={idx % 2 === 0 ? zebraLight : zebraDark}>
              {/* Sticky left metric name */}
              <td style={{ ...rowHeaderStyle, ...stickyLeft }}>
                {metric.name}
              </td>

              {metric.data.map((val, j) => (
                <td key={j} style={tdStyle}>
                  {Number(val).toLocaleString("en-GB", {
                    minimumFractionDigits: 0,
                    maximumFractionDigits: 0
                  })}
                </td>
              ))}
            </tr>
          ))}
        </tbody>

      </table>
    </div>
  );
};


/* ============================================
   MAIN COMPONENT
   ============================================ */

const PortfolioCashflowView = ({ tableData }) => {
  if (!tableData) return <div style={{ padding: 20 }}>Loading portfolio cashflows…</div>;

  return (
    <div style={{ marginTop: "2rem" }}>
      <h2 style={titleStyle}>Portfolio Monthly Cashflows</h2>
      <CashflowTable hcData={tableData} />
    </div>
  );
};

export default PortfolioCashflowView;


/* ============================================
   MODERN FINANCIAL-DASHBOARD STYLING
   ============================================ */

const tableWrapperStyle = {
  overflowX: "auto",
  border: "1px solid #e0e0e0",
  borderRadius: "10px",
  boxShadow: "0 2px 8px rgba(0,0,0,0.08)",
  background: "white",
  marginTop: "1rem",
  maxWidth: "900px"
};

const tableStyle = {
  width: "100%",
  borderCollapse: "separate",
  borderSpacing: 0,
  fontFamily: "Inter, sans-serif",
  fontSize: "11px",
  maxWidth: "1300px"
};

const thStyle = {
  top: 0,
  position: "sticky",
  background: "#2563eb",
  backdropFilter: "blur(8px)",
  padding: "5px 5px",
  fontWeight: 600,
  color: "white",
  borderBottom: "1px solid #ddd",
  borderRight: "1px solid #eee",
  zIndex: 2,
  whiteSpace: "nowrap",
  textAlign: "center"
};

const stickyLeft = {
  position: "sticky",
  left: 0,
  zIndex: 3,
  background: "#ffffff",
  borderRight: "1px solid #ddd"
};

const rowHeaderStyle = {
  padding: "7px 12px",
  fontWeight: 600,
  borderBottom: "1px solid #eee",
  background: "#ffffff",
  textAlign: "left",
  whiteSpace: "nowrap"
};

const tdStyle = {
  padding: "0px 8px",
  lineHeight: "1.0",
  height: "18px",
  borderBottom: "1px solid #f0f0f0",
  textAlign: "right",
  whiteSpace: "nowrap"
};

const zebraLight = {
  background: "#ffffff"
};

const zebraDark = {
  background: "#fafafa"
};

const titleStyle = {
  fontFamily: "Inter, sans-serif",
  fontSize: "16px",
  fontWeight: 600,
  color: "#2563eb",
  marginBottom: "1rem"
};
